const D = { energy:.55, density:.5, scale:1, speed:1, spread:.5, alpha:.7, hue:38, x:.5, y:.5, style:'dusk', act:'lek', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const clp=(v,a,b)=>Math.max(a,Math.min(b,v));
const lrp=(a,b,t)=>a+(b-a)*t;
const md=(a,n)=>((a%n)+n)%n;
const frc=v=>v-Math.floor(v);
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
const hsb2=(h,s,v)=>{h=md(h,360)/60;s=clp(s,0,1);v=clp(v,0,1);const c=v*s,x=c*(1-Math.abs(h%2-1)),m=v-c;let r=0,g2=0,b=0;
  if(h<1){r=c;g2=x;}else if(h<2){r=x;g2=c;}else if(h<3){g2=c;b=x;}else if(h<4){g2=x;b=c;}else if(h<5){r=x;b=c;}else{r=c;b=x;}
  return [(r+m)*255,(g2+m)*255,(b+m)*255];};

const W=width, Hh=height, u=Math.min(W,Hh);
const H=md(P.hue,360);
const st=P.style, act=P.act||'lek';
const isSil=st==='silhouette', isTr=st==='trails', isSch=st==='schematic';
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

const en=clp(P.energy,0,1), dn=clp(P.density,0,1), al=clp(P.alpha,0,1);
const sp=P.speed, sc=clp(P.scale,0.25,2.4), spr=clp(P.spread,0,1);
let envS=1, envA=1, wander=1;
if(act==='drift'){ wander=2.6; }
else if(act==='boil'){ envS=0.7+1.35*K.intensity; envA=0.8+0.5*K.intensity; }

const nSw=Math.max(1,Math.round(lrp(1,5,dn)));
let per=Math.round(lrp(16,64,dn)*(isTr?0.45:1));
const agit=(0.55+1.35*en)*envS;

// column centroid — slow incommensurate wander (never re-phases on the 8s gate)
const cenOf=(k,tt)=>{
  const px=fr(k*7+1), py=fr(k*7+2), q=fr(k*7+3)*6.283;
  const bx=lrp(0.14,0.86,px), by=lrp(0.18,0.82,py);
  const dx=(0.55*Math.sin(tt*0.067*sp+q)+0.3*Math.sin(tt*0.151*sp+q*1.7)+0.16*Math.sin(tt*0.023*sp))*0.16*wander;
  const dy=(0.5*Math.sin(tt*0.089*sp+q*2.3)+0.28*Math.sin(tt*0.197*sp+q*0.6))*0.09*wander;
  const ax=lrp(0.5,bx,0.35+0.65*spr)+dx, ay=lrp(0.5,by,0.35+0.65*spr)+dy;
  return [ (P.x-0.5)*W + ax*W, (P.y-0.5)*Hh + ay*Hh ];
};
// one midge: slow rise, fast drop (the real lek bob) + two-rate horizontal darting
const midge=(k,i,tt)=>{
  const c=cenOf(k,tt), j=k*997+i*13;
  const rx=u*lrp(0.012,0.075,fr(j+1))*sc*(0.5+spr), ry=u*lrp(0.02,0.13,fr(j+2))*sc*(0.5+spr);
  const rt=(0.30+fr(j+3)*0.75)*agit*sp;
  const ph=frc(fr(j+4)+tt*rt);
  const bob=ph<0.72 ? -ph/0.72 : -(1-(ph-0.72)/0.28);
  const w1=(1.1+fr(j+5)*2.9)*agit*sp, w2=(0.7+fr(j+6)*1.7)*agit*sp;
  const dx=Math.sin(tt*w1+fr(j+7)*6.283)*rx + Math.sin(tt*w1*1.618+fr(j+8)*6.283)*rx*0.42;
  const dy=bob*ry + Math.sin(tt*w2+fr(j+9)*6.283)*ry*0.22;
  return [ c[0]+dx, c[1]+dy ];
};

// ---- backlit dusk haze per column (this is what makes the swarm read at all) ----
if(!isSch){
  blendMode(ADD);
  for(let k=0;k<nSw;k++){
    const c=cenOf(k,K.t);
    const br=0.55+0.45*Math.sin(K.t*0.129*sp+fr(k+31)*6.283)+0.2*Math.sin(K.t*0.311*sp);
    const gr2=u*lrp(0.14,0.30,fr(k+32))*sc*(0.7+0.6*spr)*(1+0.09*br);
    const ga=clp((isSil?0.30:0.19)*al*(0.35+0.9*en)*envA*(0.6+0.4*br)*(1+A.lowmid*0.5),0,0.5);
    const gc=hsb2(md(H+(isSil?6:0),360), isSil?0.22:0.52, isSil?0.95:0.88);
    const rg=drawingContext.createRadialGradient(c[0],c[1],0,c[0],c[1],gr2);
    rg.addColorStop(0,'rgba('+(gc[0]|0)+','+(gc[1]|0)+','+(gc[2]|0)+','+ga.toFixed(3)+')');
    rg.addColorStop(0.45,'rgba('+(gc[0]|0)+','+(gc[1]|0)+','+(gc[2]|0)+','+(ga*0.34).toFixed(3)+')');
    rg.addColorStop(1,'rgba('+(gc[0]|0)+','+(gc[1]|0)+','+(gc[2]|0)+',0)');
    drawingContext.fillStyle=rg;
    drawingContext.fillRect(c[0]-gr2,c[1]-gr2,gr2*2,gr2*2);
  }
  blendMode(BLEND);
}

// ---- the swarm ----
for(let k=0;k<nSw;k++){
  if(isSch){ // clinical: bounding ellipse + centroid cross
    const c=cenOf(k,K.t), rr=u*0.19*sc*(0.7+0.6*spr);
    noFill(); stroke(md(H+170,360),58,92,26*al); strokeWeight(Math.max(0.5,u*0.0011));
    ellipse(c[0],c[1],rr*1.5,rr*2.1);
    stroke(md(H+170,360),40,100,44*al);
    line(c[0]-u*0.012,c[1],c[0]+u*0.012,c[1]); line(c[0],c[1]-u*0.012,c[0],c[1]+u*0.012);
  }
  for(let i=0;i<per;i++){
    const p=midge(k,i,K.t);
    const dep=fr(k*997+i*13+2);
    const rad=u*0.0022*sc*lrp(0.6,1.7,dep);
    if(isTr){
      noFill(); strokeWeight(Math.max(0.4,rad*0.9));
      for(let s2=0;s2<5;s2++){
        const a1=midge(k,i,K.t-s2*0.055), a2=midge(k,i,K.t-(s2+1)*0.055);
        stroke(md(H+lrp(-4,16,s2/5),360),lrp(34,10,s2/5),lrp(100,64,s2/5),(58-s2*10)*al*(0.4+0.7*en));
        line(a1[0],a1[1],a2[0],a2[1]);
      }
      noStroke(); fill(md(H+8,360),12,100,70*al); circle(p[0],p[1],rad*1.5);
    } else if(isSch){
      const q=midge(k,i,K.t-0.06);
      stroke(md(H+170,360),52,100,64*al); strokeWeight(Math.max(0.4,u*0.0009));
      line(p[0],p[1],p[0]+(p[0]-q[0])*2.2,p[1]+(p[1]-q[1])*2.2);
      line(p[0]-rad*1.6,p[1],p[0]+rad*1.6,p[1]); line(p[0],p[1]-rad*1.6,p[0],p[1]+rad*1.6);
    } else if(isSil){
      noStroke(); fill(md(H+200,360),18,8,clp(62+24*dep,0,92)*al);
      ellipse(p[0],p[1],rad*2.3,rad*1.5);
    } else {
      const glint=0.5+0.5*Math.sin(K.t*(5.1+dep*7.3)*sp+fr(k*997+i*13+11)*6.283);
      noStroke();
      fill(md(H+lrp(-6,18,glint),360),lrp(30,6,glint),lrp(72,100,glint),clp((44+52*glint)*(0.4+0.8*en),0,100)*al);
      circle(p[0],p[1],rad*(1.5+1.1*glint+K.pulse*0.3+A.treble*0.8));
      fill(md(H+210,360),24,14,26*al); circle(p[0],p[1],rad*0.7); // dark body under the backlit halo
    }
  }
}

blendMode(BLEND); drawingContext.shadowBlur=0; noStroke();
